package de.schaepi.puls180;
import android.content.*;import android.os.SystemClock;import android.provider.Settings;import java.nio.charset.StandardCharsets;import java.security.*;import java.security.spec.*;import java.util.*;
public final class License {
 private static final String PUBLIC="";
 private static SharedPreferences prefs(Context c){return c.getSharedPreferences("puls180_license_v1",0);}
 public static synchronized boolean revoked(Context c){return prefs(c).getBoolean("revoked",false);}
 static synchronized void markRevoked(Context c){prefs(c).edit().putBoolean("revoked",true).commit();}
 private static int boot(Context c){return Settings.Global.getInt(c.getContentResolver(),Settings.Global.BOOT_COUNT,-1);}
 private static String hashCode(String value){try{byte[] h=MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));StringBuilder out=new StringBuilder();for(int i=0;i<24;i++)out.append(String.format(Locale.ROOT,"%02X",h[i]));return out.toString();}catch(Exception e){return "";}}
 public static synchronized String code(Context c){String id=Settings.Secure.getString(c.getContentResolver(),Settings.Secure.ANDROID_ID);return id==null||id.isEmpty()?"":hashCode(c.getPackageName()+"|DEVICE|"+id);}
 private static String legacyCode(Context c){String nonce=prefs(c).getString("install","");String id=Settings.Secure.getString(c.getContentResolver(),Settings.Secure.ANDROID_ID);return nonce.isEmpty()||id==null||id.isEmpty()?"":hashCode(c.getPackageName()+"|"+id+"|"+nonce);}
 private static boolean verifyPermanent(String input,String device){try{if(device==null||!device.matches("[A-F0-9]{48}"))return false;String clean=input==null?"":input.replaceAll("\\s+","");if(clean.length()>2048)return false;String[] parts=clean.split("\\.",-1);if(parts.length!=2)return false;byte[] payload=Base64.getUrlDecoder().decode(parts[0]);if(!new String(payload,StandardCharsets.UTF_8).equals("PULS180|"+device))return false;Signature v=Signature.getInstance("SHA256withRSA");v.initVerify(KeyFactory.getInstance("RSA").generatePublic(new X509EncodedKeySpec(Base64.getDecoder().decode(PUBLIC))));v.update(payload);return v.verify(Base64.getUrlDecoder().decode(parts[1]));}catch(Exception e){return false;}}
 public static synchronized boolean activate(Context c,String input){if(revoked(c))return false;String clean=input==null?"":input.replaceAll("\\s+","");if(!verifyPermanent(clean,code(c))&&!verifyPermanent(clean,legacyCode(c)))return false;return prefs(c).edit().putString("permanent",clean).commit();}
 static synchronized boolean hasPermanentKey(Context c){String key=prefs(c).getString("permanent","");return verifyPermanent(key,code(c))||verifyPermanent(key,legacyCode(c));}
 public static synchronized boolean paid(Context c){return !revoked(c)&&hasPermanentKey(c);}
 private static synchronized boolean startTrial(Context c){SharedPreferences p=prefs(c);if(p.getLong("start",0)>0)return true;long now=System.currentTimeMillis(),elapsed=SystemClock.elapsedRealtime();int boot=boot(c);if(now<=0||boot<0)return false;return p.edit().putLong("start",now).putLong("last",now).putLong("elapsed",elapsed).putInt("boot",boot).putBoolean("clockBlocked",false).commit();}
 public static synchronized long remaining(Context c){if(paid(c))return Long.MAX_VALUE;if(!startTrial(c))return 0;SharedPreferences p=prefs(c);if(p.getBoolean("clockBlocked",false))return 0;long start=p.getLong("start",0),wall=System.currentTimeMillis(),elapsed=SystemClock.elapsedRealtime();int boot=boot(c);long now=TrialPolicy.effective(wall,p.getLong("last",0),elapsed,p.getLong("elapsed",-1),boot,p.getInt("boot",-1));if(now<0){p.edit().putBoolean("clockBlocked",true).commit();return 0;}if(!p.edit().putLong("last",now).putLong("elapsed",elapsed).putInt("boot",boot).commit())return 0;return TrialPolicy.remaining(start,now);}
 public static boolean allowed(Context c){return !revoked(c)&&(paid(c)||remaining(c)>0);}
 public static boolean activated(Context c){return prefs(c).getLong("start",0)>0;}
 public static long expires(Context c){long start=prefs(c).getLong("start",0);return start>0?start+TrialPolicy.DURATION:0;}
 public static String status(Context c){if(revoked(c))return "Freischaltung gesperrt. Der Kauf wurde zurückgegeben oder storniert. Bei Fragen bitte den Anbieter von Puls 180 kontaktieren.";if(paid(c))return "Dauerhaft freigeschaltet";long left=remaining(c);if(prefs(c).getBoolean("clockBlocked",false))return "Test gesperrt: Die Gerätezeit konnte nicht sicher geprüft werden. Bitte den Anbieter von Puls 180 kontaktieren.";if(left<=0)return "Die vierzehn Testtage sind abgelaufen. Deine Messungen bleiben gespeichert. Mit einem Kaufschlüssel kannst du Puls 180 dauerhaft freischalten.";return "Test aktiv – noch "+((left+3599999)/3600000)+" Stunden.\nEnde: "+java.time.Instant.ofEpochMilli(expires(c)).atZone(java.time.ZoneId.systemDefault()).format(java.time.format.DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm"));}
}



